		if (this.fn) this.fn(deltaTime);
		const redirect = this.next;
		if (this._destroyed) this.next = null;
		return redirect;
	}

	connect(previous) {
		this.previous = previous;
		if (previous.next) previous.next.previous = this;
		this.next = previous.next;
		previous.next = this;
	}

