/**
 * 4x8 bitmap font, reused from Echoes (`Echoes/js/scene/scene.js` +
 * `Echoes/assets/fonts/font4x8.png`, copied to `assets/fonts/font4x8.png`).
 *
 * The character order below is Echoes' verbatim, so glyph columns line up with
 * the shipped atlas. Everything the game prints — HUD, menus, level select,
 * pause — goes through here; there is no DOM or browser-font text anywhere,
 * which is what keeps the whole frame inside the 176x144 pixel buffer.
 */

export const CHAR_WIDTH = 4;
export const CHAR_HEIGHT = 8;

// Verbatim from Echoes. Duplicate entries (the quote family, ':') resolve to
// the last index, exactly as Echoes' map builder does.
const CHARS = ` ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.,''''"'?!@_*:$%+-/:;<=>`;

export class BitmapFont {
	constructor(image) {
		this.image = image;
		this.charWidth = CHAR_WIDTH;
		this.charHeight = CHAR_HEIGHT;
		this.glyphs = {};
		const chars = CHARS.split('');
		for (let i = 0; i < chars.length; i++) {
			this.glyphs[chars[i]] = {
				x: i * CHAR_WIDTH,
				y: 0,
				width: CHAR_WIDTH,
				height: CHAR_HEIGHT,
			};
		}
		this.fallback = this.glyphs[' '];
	}

	glyph(char) {
